package com.personal.assistant.module.system.service;
import com.personal.assistant.module.system.dto.*;import lombok.extern.slf4j.Slf4j;import org.quartz.Scheduler;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.sql.DataSource;import java.io.File;import java.sql.Connection;import java.time.LocalDateTime;
@Slf4j @Service public class SystemService {private final DataSource dataSource;private final Scheduler scheduler;@Value("${spring.application.name:personal-assistant-server}")private String appName;@Value("${app.storage.path:/app}")private String storagePath;@Value("${app.storage.warning-percent:85}")private double warningPercent;public SystemService(DataSource d,Scheduler s){dataSource=d;scheduler=s;}public HealthInfo checkHealth(){String db=checkDatabase();return new HealthInfo("UP".equals(db)?"UP":"DOWN",db,appName,version(),LocalDateTime.now());}public String version(){return appName+" v0.0.1";}public SystemStatus status(){return new SystemStatus(appName,version(),checkDatabase(),checkScheduler(),"JDBC",storage(),LocalDateTime.now());}public StorageInfo storage(){File f=new File(storagePath);if(!f.exists())f=new File(".");long total=f.getTotalSpace(),free=f.getFreeSpace(),usable=f.getUsableSpace();double used=total==0?0:(double)(total-free)*100/total;return new StorageInfo(f.getAbsolutePath(),total,free,usable,Math.round(used*100.0)/100.0,used>=warningPercent?"WARNING":"OK");}private String checkScheduler(){try{return scheduler.isStarted()&&!scheduler.isShutdown()?"UP":"DOWN";}catch(Exception e){log.warn("调度器状态检查失败",e);return "DOWN";}}private String checkDatabase(){try(Connection c=dataSource.getConnection()){return c.isValid(2)?"UP":"DOWN";}catch(Exception e){log.error("数据库健康检查失败",e);return "DOWN";}}}